def snapshot():
    # A fresh graph avoids one offline run mutating the next run's sample.
    return json.loads(_DATA)


class DemoService:
    def __init__(self, root):
        self.root = root
        self.data = snapshot()

    def snapshot(self):
        return self.data

    def status(self):
        return {"state": "demo", "pending": 0}

    def command(self, command):
        kind = command.get("kind")
        table = "chores" if kind == "chore" else "shopping" if kind == "shopping" else "devices"
        for row in self.data.get(table, []):
            if row.get("id") == command.get("id"):
                if kind == "device":
                    row.update(command.get("state") or {})
                else:
                    row["done"] = command.get("done", False)
                    if command.get("done_by"):
                        row["done_by"] = command["done_by"]
                row["version"] = row.get("version", 1) + 1
                self.data["revision"] = self.data.get("revision", 1) + 1
                break

    def poll(self, now_ms):
        return False

    def photo_path(self, photo):
        return self.root + "/" + photo.get("asset", "assets/photo-coast.png")

    def close(self):
        pass
